import{_ as n,C as i,o as r,c as o,ag as t,E as s}from"./chunks/framework.Drp2S_UI.js";const f=JSON.parse('{"title":"Performance optimization principles","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/performance-principles.md","filePath":"en/guide/performance-principles.md","lastUpdated":1793689268000}'),d={name:"en/guide/performance-principles.md"};function c(l,e,p,h,u,m){const a=i("MermaidDiagram");return r(),o("div",null,[e[0]||(e[0]=t('<h1 id="performance-optimization-principles" tabindex="-1">Performance optimization principles <a class="header-anchor" href="#performance-optimization-principles" aria-label="Permalink to &quot;Performance optimization principles&quot;">​</a></h1><p>This page explains how the current implementation reduces repeated work during typing, sustained deletion and Chinese composition. See <a href="./benchmark.html">Benchmark</a> for measurements and <a href="./lab.html">experimental configuration</a> for switches and limits. Baseline remains the default. Both <code>imePreview</code> and <code>imeWorkerPreview</code> default to false; selecting sync/worker does not enable them. Release acceptance remains hold.</p><h2 id="where-input-latency-comes-from" tabindex="-1">Where input latency comes from <a class="header-anchor" href="#where-input-latency-comes-from" aria-label="Permalink to &quot;Where input latency comes from&quot;">​</a></h2><p>An edit can trigger paragraph scanning, HarfBuzz shaping, line breaking, pagination, position/query-index commits, font coverage, painting, caret placement and tools. Repeating the full pipeline for every pinyin intermediate state scales with the document. Moving work to a Worker reduces main-thread occupancy but retains the computation, transport and queueing costs.</p><p>Measure handler time and update-to-geometry latency separately. A short handler can simply mean that expensive work was deferred.</p><table tabindex="0"><thead><tr><th>Technique</th><th>Work avoided</th><th>Remaining cost</th></tr></thead><tbody><tr><td>Paragraph caches and incremental flow</td><td>Unchanged shaping, breaking and flow</td><td>Dependency checks and affected pagination</td></tr><tr><td>Range position/query commits</td><td>Rebuilding unchanged character positions/indexes</td><td>Global metadata and line/paragraph directories</td></tr><tr><td>Latest composition state per frame</td><td>Computing states superseded in the same frame</td><td>Frame wait and final commit</td></tr><tr><td>Local preview/window</td><td>Full-document/full-paragraph layout</td><td>Convergence checks, page paint and fallbacks</td></tr><tr><td>Deferred derived work</td><td>Repeated full coverage/highlight/tool refresh</td><td>Query/export/finalization barriers</td></tr><tr><td>Cell layout cache</td><td>Unchanged text-cell child layout</td><td>Table checks, changed cells and grid propagation</td></tr><tr><td>Worker and queue control</td><td>Migratable main-thread layout and redundant queueing</td><td>DTOs, transfer, waiting and main-thread commit</td></tr></tbody></table><h2 id="reuse-paragraphs-flow-and-positions-separately" tabindex="-1">Reuse paragraphs, flow and positions separately <a class="header-anchor" href="#reuse-paragraphs-flow-and-positions-separately" aria-label="Permalink to &quot;Reuse paragraphs, flow and positions separately&quot;">​</a></h2><p>Paragraph shaping/breaking can be reused when both content and layout dependencies match. Font revision, width and relevant style changes invalidate the result. Glyph-path and shaping-run caches reduce repeated outline construction/shaping; they do not remove required line-breaking or pagination validation.</p><p><code>IncrementalFlow</code> retains input/output checkpoints. After an edit, it recomputes the affected range and reuses the suffix only when flow state, dependencies and page constraints converge exactly. Height, floats or width changes may propagate further. Batch suffix reuse still validates paragraph metadata and distinct page checkpoints.</p><p>Position commits reuse line/position blocks. Source-offset views represent logical index shifts after an insertion without copying all later characters or rebuilding unchanged query character tables. Readers see current indices/coordinates while old references remain valid. Global directories still require work: this is not O(1).</p><p>Implementation: <code>IncrementalFlow.ts</code>, <code>relativeLayout.ts</code>, <code>Position.ts</code> and <code>PositionList.ts</code> under <code>src/editor/core/layout/</code> and <code>core/position/</code>.</p><h2 id="composition-previews-before-formal-commits" tabindex="-1">Composition previews before formal commits <a class="header-anchor" href="#composition-previews-before-formal-commits" aria-label="Permalink to &quot;Composition previews before formal commits&quot;">​</a></h2><p><code>CompositionSession</code> retains the latest value and sequence. <code>input</code> is authoritative; <code>compositionupdate</code> does not independently edit the model. If <code>n</code> is superseded by <code>ni</code> before the frame consumes it, <code>n</code> is counted as merged, not displayed.</p>',13)),s(a,{code:`flowchart TD
  Input[Latest composing input] --> Pending[Replace pending value and sequence]
  Pending --> Frame[rAF consumer]
  Pending --> Timer[50ms scheduling fallback]
  Frame --> Eligible{Eligible for local preview}
  Timer --> Eligible
  Eligible -->|yes| Preview[Temporary HarfBuzz row or window]
  Preview --> Valid{Surrounding breaks and metrics converge}
  Valid -->|yes| Paint[Replace target row and paint page]
  Valid -->|no| Full[Authoritative synchronous layout]
  Eligible -->|no| Full
  Paint --> Anchor[Update caret and native input anchor]
  Full --> Anchor
  End[End or public query command] --> Barrier[Materialize latest state and invalidate old work]
  Barrier --> Commit[Commit or restore cancellation]
`}),e[1]||(e[1]=t('<p>The frame and timer consume the same pending state; the first cancels the other. 50ms is a scheduling fallback, not a debounce or a latency guarantee while blocked. For cheap edits, waiting for a frame can increase geometry latency.</p><p>The temporary preview still uses HarfBuzz glyphs, line breaking and carets. It does not estimate width from character counts or use browser text APIs. A successful preview keeps the formal model, substitutes the target row and paints the composition underline. The whole containing page is painted; this is not Tile rendering.</p><p>Long-paragraph windows contain the target and available neighboring rows, limited to 2048 elements and safe complete wrap-unit boundaries. Surrounding source ranges, glyphs, carets, heights and baselines must converge. Changed wrapping/dependencies cause fallback. The window currently supports eligible Latin/Han/Common/Inherited text with uniform metric styles, not arbitrary BiDi/contextual scripts or containers.</p><p>Final selection becomes a formal transaction; cancellation restores content/range. Intermediate previews are not separate undo records. Public content/geometry queries materialize the current composition and derived state; public mutations finish the session. These barriers can incur full layout and must remain part of correctness.</p><p>Implementation: <code>CompositionSession.ts</code>, <code>CanvasEvent.ts</code>, <code>CompositionPreview.ts</code>.</p><h2 id="defer-derived-work-and-share-anchor-geometry" tabindex="-1">Defer derived work and share anchor geometry <a class="header-anchor" href="#defer-derived-work-and-share-anchor-geometry" aria-label="Permalink to &quot;Defer derived work and share anchor geometry&quot;">​</a></h2><p>Full font coverage, search/control highlights and tool geometry need not be published for each pinyin state. Composition marks them dirty, scans only required local font coverage and retains missing-font downloads. Finalization/query/export restores the complete authoritative state through <code>flushCompositionDerivedState()</code>. Changed font or auxiliary-content dependencies can still force full scans. Deferred work remains a finalization cost rather than disappearing.</p><p><code>CompositionAnchor</code> shares the latest caret with the native textarea. It reads the container, scroll ancestors and visual viewport before writing styles/scroll, and coalesces placement in a microtask within the current frame. It preserves textarea value/selection owned by native composition. Scrolling/resizing repositions the anchor without immediately undoing manual scrolling. DOM coordinates do not prove that a real OS candidate window follows correctly.</p><h2 id="cell-caching-and-protected-admission" tabindex="-1">Cell caching and protected admission <a class="header-anchor" href="#cell-caching-and-protected-admission" aria-label="Permalink to &quot;Cell caching and protected admission&quot;">​</a></h2><p>Text-cell reuse checks content, element identities and layout dependencies. Hits project current revisions instead of repeating child layout. Unchanged table structure and cell heights permit grid reuse. Height changes still propagate row constraints and pagination; unsupported nested/stateful content follows ordinary recursion.</p><p>The cache allows 512 entries and an internally estimated 16 MiB. A plain LRU scanning 600 cells can repeatedly evict the next pass&#39;s useful entries. Admission now protects entries used in the current/previous pass, accepts a candidate only if it fits fully, and otherwise skips it without partial eviction. Eviction candidates are built once per pass; old documents become reclaimable after a full idle pass.</p><p>A stable 600-cell scan can therefore reuse 512 and compute 88. It still checks the whole table. <code>computedCells</code> counts child layout, not HarfBuzz cache misses; estimated <code>bytes</code> is not actual process/WASM/GPU memory. Implementation: <code>TableLayoutCache.ts</code>.</p><h2 id="worker-freshness-and-recovery" tabindex="-1">Worker freshness and recovery <a class="header-anchor" href="#worker-freshness-and-recovery" aria-label="Permalink to &quot;Worker freshness and recovery&quot;">​</a></h2><p>Ordinary Worker editing maintains an ordered model mirror. Sustained deletion keeps synchronous geometry commits while coalescing paint. Bounded transaction/byte queues and ordered acknowledgments prevent unbounded accumulation. Faults or budget excess rebuild the mirror from the current authoritative model without losing confirmed edits.</p><p>IME Worker preview is separate and experimental: temporary body-paragraph layout moves to the Worker; input, validation, formal commits, painting and anchors remain on the main thread. It does not add asynchronous table layout. Replies must match session, sequence, document/geometry/font/constraint revisions. Stale replies are discarded. Failure/50ms fallback uses synchronous layout; ending/cancelling/destroying invalidates old replies without implying that in-flight computation has stopped.</p><p>End-to-end cost includes DTO preparation, messaging, queueing, computation, return, validation and paint. Reduced handler time with worse geometry is not a refresh win. <code>imeWorkerPreview</code> stays false and profiles do not automatically enable transfer.</p><h2 id="webgl-webgpu-and-current-scope" tabindex="-1">WebGL/WebGPU and current scope <a class="header-anchor" href="#webgl-webgpu-and-current-scope" aria-label="Permalink to &quot;WebGL/WebGPU and current scope&quot;">​</a></h2><p>These optimizations do not implement WebGL/WebGPU layout or GPU Tile rendering. HarfBuzz/WASM, flow, indexes, history and dependency checks remain on existing CPU/ Worker paths, with Canvas path drawing. Browser Canvas acceleration is not a project GPU layout implementation. Benefits here come from avoiding work, reducing scope and scheduling. A future GPU path would need separate resource/precision/pixel/transport validation and fresh geometry, presentation and memory measurements.</p><h2 id="reading-and-reproducing-the-evidence" tabindex="-1">Reading and reproducing the evidence <a class="header-anchor" href="#reading-and-reproducing-the-evidence" aria-label="Permalink to &quot;Reading and reproducing the evidence&quot;">​</a></h2><p>See <a href="./benchmark.html#final-automated-results">latest automated results</a>. The five-scene baseline→sync comparison combines multiple changes; it cannot attribute all benefits to one switch. The large-table toggle and historical IME-10/11/12/13 studies isolate their own scope. Older dated measurements retain their original source/methodology. The current long fixture edits near the paragraph beginning, unlike IME-11&#39;s final-row window cases; those gains do not establish arbitrary-position reuse.</p><ul><li>Handler: event-function duration, possibly reduced by deferring work.</li><li>Geometry: update-to-consumption proxy including scheduling, not screen presentation.</li><li>Next rAF: update-to-next-callback after consumption, not actual FPS.</li><li>P50/P95/P99/max: sorted percentiles and maximum; per-trial ranges differ from pooled distributions.</li><li>Counters: distinguish received, merged, consumption submissions and pending updates handled at end; finalized is not the number of final selections. Unsupported Long Tasks APIs are unavailable. Closure frame gaps include commit/history work and cannot establish preedit FPS.</li></ul><p>Start Vite and run <code>npm run test:performance:ime:release</code> with <code>BASE_URL</code>. Runtime configuration and commands are in the <a href="./../../guide/ime-performance-tasks.html">acceptance instructions</a>. Quality/correctness run before serial timing; each mode is warmed up and order alternates over three trials. JSON retains environment, timestamps, source/font/tool/configuration fingerprints and distributions; raw text/screenshots are not committed.</p><p>Synthetic input cannot establish native macOS/Windows IME/candidate behavior, mobile experience or long-term memory stability. Budgets remain handler P95 ≤8ms and geometry P95 ≤32ms. Missing manual evidence or failed budgets keep hold.</p>',23))])}const b=n(d,[["render",c]]);export{f as __pageData,b as default};
